const medicineState={wavelength:470,irradiance:8,expression:70,frequency:12,mode:'excite'};
const neuronNodes=Array.from({length:34},(_,i)=>({x:.08+((i*47)%89)/100*.84,y:.12+((i*31)%83)/100*.76,z:(Math.sin(i*2.17)+1)/2}));
function medicineResponse(){const optimum=medicineState.mode==='excite'?470:590;const spectral=Math.exp(-Math.pow((medicineState.wavelength-optimum)/42,2));const dose=medicineState.irradiance/20*medicineState.expression/100;const pulse=.45+.55*Math.min(1,medicineState.frequency/25);return DemoKit.clamp(spectral*dose*pulse*1.55,0,1)}
function updateMedicine(){const r=medicineResponse(),sign=medicineState.mode==='excite'?1:-1;DemoKit.metric('membraneOutput',`${sign>0?'+':'−'}${Math.round(8+28*r)} mV`);DemoKit.metric('activeCells',`${Math.round(r*100)}%`);DemoKit.metric('behaviorOutput',r<.12?'Minimal':medicineState.mode==='excite'?'Excitation':'Inhibition')}
function wavelengthColor(w){if(w<500)return'#57dcff';if(w<565)return'#65dfa5';if(w<610)return'#ffd866';return'#ff7a72'}
const medicineController=DemoKit.animator(document.getElementById('medicineCanvas'),(ctx,w,h,t)=>{DemoKit.clear(ctx,w,h);const r=medicineResponse(),pulse=.35+.65*Math.max(0,Math.sin(t*medicineState.frequency*Math.PI*2));const beamX=w*(.24+.52*(medicineState.wavelength-450)/200);const beam=ctx.createLinearGradient(beamX,20,beamX,h*.8);beam.addColorStop(0,wavelengthColor(medicineState.wavelength)+'cc');beam.addColorStop(1,wavelengthColor(medicineState.wavelength)+'00');ctx.fillStyle=beam;ctx.beginPath();ctx.moveTo(beamX-w*.08,0);ctx.lineTo(beamX+w*.08,0);ctx.lineTo(beamX+w*.24,h);ctx.lineTo(beamX-w*.24,h);ctx.closePath();ctx.fill();
  ctx.lineWidth=1;neuronNodes.forEach((a,i)=>neuronNodes.slice(i+1).forEach(b=>{const dx=(a.x-b.x)*w,dy=(a.y-b.y)*h;if(dx*dx+dy*dy<(w*.18)**2){ctx.strokeStyle='#31425788';ctx.beginPath();ctx.moveTo(a.x*w,a.y*h);ctx.lineTo(b.x*w,b.y*h);ctx.stroke()}}));
  neuronNodes.forEach((n,i)=>{const proximity=Math.max(0,1-Math.abs(n.x*w-beamX)/(w*.3));const active=DemoKit.clamp(r*proximity*(.75+.25*Math.sin(i)),0,1);const radius=3+n.z*3+active*5*pulse;ctx.shadowBlur=active*18;ctx.shadowColor=medicineState.mode==='excite'?'#ffdf6b':'#a78bfa';ctx.fillStyle=active>.18?(medicineState.mode==='excite'?'#ffdf6b':'#a78bfa'):'#65758d';ctx.beginPath();ctx.arc(n.x*w,n.y*h,radius,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0});
  ctx.fillStyle='#9eacc0';ctx.font='11px ui-monospace,monospace';ctx.fillText(`${medicineState.wavelength} nm · ${medicineState.irradiance.toFixed(1)} mW/mm²`,18,h-22);updateMedicine()});
DemoKit.range('wavelength','wavelengthValue',v=>`${v} nm`,v=>medicineState.wavelength=v);DemoKit.range('irradiance','irradianceValue',v=>`${v.toFixed(1)} mW/mm²`,v=>medicineState.irradiance=v);DemoKit.range('expression','expressionValue',v=>`${v}%`,v=>medicineState.expression=v);DemoKit.range('frequency','frequencyValue',v=>`${v} Hz`,v=>medicineState.frequency=v);DemoKit.choices('[data-choice="opsin"] button',v=>{medicineState.mode=v;updateMedicine()});DemoKit.wireButton(medicineController);document.getElementById('resetDemo').addEventListener('click',()=>{[['wavelength',470],['irradiance',8],['expression',70],['frequency',12]].forEach(([id,v])=>{const el=document.getElementById(id);el.value=v;el.dispatchEvent(new Event('input'))});document.querySelector('[data-choice="opsin"] button[data-value="excite"]').click();medicineController.reset()});updateMedicine();
